package com.bank.account.service;

import com.bank.account.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Slf4j
@Service
public class AccountService {

    @PersistenceContext
    private EntityManager em;

    // persist(): brand new account, SAME object stays managed
    @Transactional
    public Account openAccount(String id, String name, BigDecimal opening) {
        Account acc = new Account(id, name, opening);
        em.persist(acc);              // schedules INSERT, acc is now managed
        acc.setAddress("Branch default");  // tracked by dirty checking → UPDATE on flush
        log.info("Opened account {} via persist()", id);
        return acc;                   // safe to return the same instance
    }

    // merge(): detached entity edited outside the transaction
    @Transactional
    public Account updateFromDetached(Account detached) {
        Account managed = em.merge(detached);  // copies state onto managed copy
        log.info("Merged account {}; detached==managed? {}", managed.getId(),
                 detached == managed);          // false
        return managed;                          // MUST use returned managed object
    }
}
